class FieldParent { String label = "parent"; String read(){ return label; } }
class FieldChild extends FieldParent { String label = "child"; @Override String read(){ return label; } }
public class FieldHidingDemo {
    public static void main(String[] args){
        FieldParent ref = new FieldChild();
        System.out.println(ref.label);
        System.out.println(ref.read());
    }
}
